        });
      }

      if (plan.scriptId) {
        const timer = window.setTimeout(() => runDemoScriptV2(plan.scriptId, plan), 120);
        stateV2.scriptTimers.push(timer);
      }
    }

    function executeVisualV2(plan, bubbleCopy) {
      stateV2.currentPlan = plan;
      stateV2.currentAgentId = plan.agent.id;
      hideListenOverlayV2();
      elsV2.mainInput.value = plan.text;
      applyToolStateV2(plan.toggles || []);
      highlightAgentV2(plan.agent.id);
      pointToAgentV2(plan.agent.id);
      showBubbleV2({
        title: `${plan.agent.name} 已承接`,
        copy: bubbleCopy,
        quickItems: DEMO_COMMANDS_V2.filter((item) => item.phrase !== plan.text),
        sticky: false
      });
    }

    function executeWorkspaceV2(plan) {
      if (!plan || !plan.agent || stateV2.isExecuting) return;
      stateV2.isExecuting = true;
      clearScriptTimersV2();
      executeVisualV2(plan, `我已直接为你打开 ${plan.targetPage}，现在可以继续追问或直接做演示动作。`);
      setPetStatusV2(stateV2.standbyEnabled ? "直达语音待命中，可继续说下一条命令" : "工作台已打开，可继续用语音或快捷命令演示");
      speakV2(plan.metric ? `${plan.entities.period}的${plan.metric.label}已经帮你直接打开。` : `已为你打开${plan.agent.name}`);
      window.setTimeout(() => {
        openModalV2(plan);
        stateV2.isExecuting = false;
      }, 640);
    }

    function executeAnswerV2(plan) {
      clearScriptTimersV2();
      executeVisualV2(plan, "这个问题我可以先直接回答，如果你需要，我再继续展开到具体工作台。");
      setPetStatusV2("已直接回答问题，可继续追问或展开到具体工作台");
      speakV2(plan.answerPayload.summary);
      window.setTimeout(() => openModalV2(plan), 260);
    }

    function executeScriptedFlowV2(plan) {
      if (!plan || !plan.agent || stateV2.isExecuting) return;
      clearScriptTimersV2();
      if (plan.route.id === "script-answer-then-contract") {
        const answerAgent = getAgentV2("agent-zonghe");
        const answerPlan = {
          ...plan,
          agent: answerAgent,
          action: "answer_direct",
          toggles: ["knowledgeQA"],
          targetPage: answerAgent.destinationView,
          scriptId: null
        };
        const contractPlan = {
          ...plan,
          action: "open_workspace",
          targetPage: plan.agent.destinationView,
          chainPrelude: "海小南已先答复制度流程，再继续为你打开合同交底表。",
          scriptId: null
        };
        executeVisualV2(contractPlan, "我会先给你制度答复，再直接打开合同交底表，体现核心智能体的串行调度能力。");
        setPetStatusV2("串行调度中：先答复制度，再打开合同交底表");
        stateV2.pendingModalPlan = contractPlan;
        openModalV2(answerPlan);
        runDemoScriptV2(plan.scriptId, answerPlan);
        speakV2(plan.answerPayload.summary);
        return;
      }
      if (plan.route.id === "script-budget-then-archive") {
        const metricPlan = {
          ...plan,
          agent: getAgentV2("agent-jicai"),
          action: "open_metric_page",
          targetPage: plan.metric.targetPage,
          toggles: ["deepThink", "webSearch"],
          scriptId: null
        };
        const archivePlan = {
          ...plan,
          metric: null,
          action: "open_workspace",
          targetPage: plan.agent.destinationView,
          scriptId: null
        };
        executeVisualV2(metricPlan, "我会先带你看本月预算完成率，再继续打开档案归档，体现核心智能体先判断再分发。");
        setPetStatusV2("串行动作中：先看预算指标，再落到归档工作台");
        stateV2.pendingModalPlan = archivePlan;
        openModalV2(metricPlan);
        runDemoScriptV2(plan.scriptId, metricPlan);
        speakV2(`${metricPlan.entities.period}的${metricPlan.metric.label}已经先帮你打开。`);
        return;
      }
      executeWorkspaceV2(plan);
    }

    function processCommandV2(text, source = "manual") {
      const commandText = String(text || "").trim();
      if (!commandText) return;
      const voiceDriven = source === "voice_text" || source === "direct";
      elsV2.mainInput.value = commandText;
      setStateV2("thinking", voiceDriven ? 760 : 520);
      if (voiceDriven) updateVoicePresenceV2(source === "direct" ? "direct" : "text", "thinking", commandText);
      else setPetStatusV2(`识别指令：${commandText}`);
      setPetStatusV2(`识别指令：${commandText}`);
      if (voiceDriven) updateVoicePresenceV2(source === "direct" ? "direct" : "text", "thinking", commandText);
      else setPetStatusV2(`识别指令：${commandText}`);
      const route = resolveRouteV2(commandText);
      if (!route) {
        if (stateV2.currentPlan) {
          handleFollowV2(stateV2.currentPlan, commandText);
          return;
        }
        toastV2("暂未匹配到明确场景，你可以先用预设命令走演示链路。", "warning", "未匹配意图");
        showBubbleV2({
          title: "我还没完全听懂",
          copy: "这句话暂未命中演示脚本，不过你可以直接点下面的预设命令继续演示。",
          quickItems: DEMO_COMMANDS_V2,
          sticky: true
        });
        return;
      }
      const plan = buildPlanV2(route, commandText, source);
      if (!plan) return;
      if (plan.action === "wake") {
        activateWakeV2("manual");
        return;
      }
      if (plan.action === "answer_direct") {
        executeAnswerV2(plan);
        return;
      }
      if (plan.action === "run_demo_script") {
        executeScriptedFlowV2(plan);
        return;
      }
      executeWorkspaceV2(plan);
    }

    function simulateCommandV2(phrase) {
      hideBubbleV2();
      showListenOverlayV2("演示回放中...", phrase);
      setStateV2("thinking");
      window.setTimeout(() => {
        hideListenOverlayV2();
        processCommandV2(phrase, "fallback");
      }, 620);
    }

    function queueVoiceCommandV2(text, source = "voice_text") {
      const content = String(text || "").trim();
      if (!content) return;
      updateVoicePresenceV2(source === "direct" ? "direct" : "text", "thinking", content);
      window.setTimeout(() => processCommandV2(content, source), 260);
    }

    async function ensureVoicePermissionV2() {
      if (!window.isSecureContext && location.hostname !== "localhost" && location.hostname !== "127.0.0.1") {
        throw new Error("当前页面不是安全上下文，请通过 localhost 打开 demo。");
      }
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error("当前浏览器不支持麦克风能力，请使用 Chrome 或 Edge。");
      }
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach((track) => track.stop());
    }

    function createRecognitionV2({ continuous = false, interimResults = true } = {}) {
      const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
      if (!SpeechRecognition) return null;
      const recognition = new SpeechRecognition();
      recognition.lang = "zh-CN";
      recognition.continuous = continuous;
      recognition.interimResults = interimResults;
      recognition.maxAlternatives = 1;
      return recognition;
    }

    function stopTextVoiceV2(forceStop = false) {
      stateV2.textListening = false;
      elsV2.micTrigger.classList.remove("listening");
      hideListenOverlayV2();
      stopVoiceMeterV2();
      if (forceStop && stateV2.textRecognition) {
        try { stateV2.textRecognition.stop(); } catch (error) {}
      }
      setStateV2(restingStateV2());
      setPetStatusV2(stateV2.standbyEnabled ? "直达语音待命中：先说“小南小南”再下达指令" : "文本语音可用，也可直接启用直达语音");
    }

    async function startTextVoiceV2() {
      if (stateV2.textListening) {
        stopTextVoiceV2(true);
        return;
      }
      try {
        await ensureVoicePermissionV2();
      } catch (error) {
        toastV2(error.message, "error", "语音权限");
        showBubbleV2({
          title: "麦克风尚未就绪",
          copy: "你仍然可以点击预设命令，或者先用文本输入继续演示。",
          quickItems: DEMO_COMMANDS_V2,
          sticky: true
        });
        return;
      }
      if (!stateV2.textRecognition) stateV2.textRecognition = createRecognitionV2({ continuous: false, interimResults: true });
      if (!stateV2.textRecognition) {
        toastV2("浏览器不支持 Web Speech API，请使用快捷语句继续演示。", "warning", "语音识别");
        return;
      }
      stateV2.textListening = true;
      elsV2.micTrigger.classList.add("listening");
      setStateV2("listening");
      await startVoiceMeterV2("text");
      updateVoicePresenceV2("text", "listening");
      setPetStatusV2("正在把语音转成文本，识别完成后会直接调度场景");
      showListenOverlayV2("正在聆听...", "请开始说话，我会先把语音转成文字。");
      let finalText = "";
      stateV2.textRecognition.onresult = (event) => {
        let interim = "";
        for (let i = event.resultIndex; i < event.results.length; i += 1) {
          const transcript = event.results[i][0].transcript;
          if (event.results[i].isFinal) finalText += transcript;
          else interim += transcript;
        }
        const display = `${finalText}${interim}`.trim();
        elsV2.mainInput.value = display;
        updateVoicePresenceV2("text", interim ? "listening" : "thinking", display || "继续说，我在听");
        showListenOverlayV2(interim ? "正在聆听..." : "识别中...", display || "请继续说话");
      };
      stateV2.textRecognition.onerror = (event) => {
        stopTextVoiceV2(false);
        toastV2(`语音识别失败：${event.error}`, "error", "语音识别");
      };
      stateV2.textRecognition.onend = () => {
        stopTextVoiceV2(false);
        if (finalText.trim()) queueVoiceCommandV2(finalText.trim(), "voice_text");
      };
      stateV2.textRecognition.start();
    }

    function stripWakeV2(text) {
      let value = normalizeV2(text);
      WAKE_WORDS.forEach((word) => {
        value = value.replaceAll(normalizeV2(word), "").trim();
      });
      return value;
    }

    function activateWakeV2(source = "direct") {
      stateV2.wakeUntil = Date.now() + 10000;
      setStateV2("awake", 1600);
      setPetStatusV2("已唤醒：10 秒内可直接说业务指令");
      toastV2("海小南已唤醒，你可以继续直接说业务需求。", "success", "语音唤醒");
      showBubbleV2({
        title: "海小南已唤醒",
        copy: source === "direct" ? "请继续直接说业务指令，我会立刻帮你调度。" : "现在你可以继续说业务需求，也可以直接点下面的预设命令。",
        quickItems: DEMO_COMMANDS_V2.filter((item) => item.phrase !== "小南小南"),
        sticky: true
      });
    }

    function stopDirectVoiceV2(forceStop = false) {
      stateV2.standbyEnabled = false;
      stateV2.directListening = false;
      elsV2.directVoiceTrigger.classList.remove("active", "listening");
      stopVoiceMeterV2();
      stateV2.wakeUntil = 0;
      if (forceStop && stateV2.directRecognition) {
        try { stateV2.directRecognition.stop(); } catch (error) {}
      }
      setStateV2("idle");
      setPetStatusV2("直达语音已关闭，你仍可用文本语音或快捷命令继续演示");
    }

    function processDirectSpeechV2(text) {
      const value = normalizeV2(text);
      const hasWakeWord = includesAnyV2(value, WAKE_WORDS);
      const stripped = stripWakeV2(value);
      if (hasWakeWord && stripped) {
        activateWakeV2("direct");
        stateV2.wakeUntil = 0;
        queueVoiceCommandV2(stripped, "direct");
        return;
      }
      if (hasWakeWord) {
        activateWakeV2("direct");
        return;
      }
      if (Date.now() < stateV2.wakeUntil) {
        stateV2.wakeUntil = 0;
        queueVoiceCommandV2(value, "direct");
        return;
      }
      showBubbleV2({
        title: "直达语音待命中",
        copy: "先说“小南小南”，再直接下达业务指令，我会更像 Siri 一样帮你调度。",
        quickItems: DEMO_COMMANDS_V2,
        sticky: false
      });
    }

    function beginDirectVoiceV2() {
      if (!stateV2.directRecognition || stateV2.directListening || !stateV2.standbyEnabled) return;
      try {
        stateV2.directRecognition.start();
        stateV2.directListening = true;
        elsV2.directVoiceTrigger.classList.add("active", "listening");
        setStateV2("standby");
        if (!stateV2.voiceStream) startVoiceMeterV2("direct").catch(() => {});
        updateVoicePresenceV2("direct", "standby");
        setPetStatusV2("直达语音待命中：先说“小南小南”再下达指令");
      } catch (error) {}
    }

    async function toggleDirectVoiceV2() {
      if (stateV2.standbyEnabled) {
        stopDirectVoiceV2(true);
        return;
      }
      try {
        await ensureVoicePermissionV2();
      } catch (error) {
        toastV2(error.message, "error", "语音权限");
        showBubbleV2({
          title: "无法进入待命",
          copy: "当前浏览器没有拿到麦克风权限，你仍然可以用文本语音或快捷命令继续演示。",
          quickItems: DEMO_COMMANDS_V2,
          sticky: true
        });
        return;
      }
      if (!stateV2.directRecognition) stateV2.directRecognition = createRecognitionV2({ continuous: true, interimResults: true });
      if (!stateV2.directRecognition) {
        toastV2("浏览器不支持直达语音待命，请改用文本语音或快捷命令。", "warning", "直达语音");
        return;
      }
      stateV2.directRecognition.onresult = (event) => {
        let finalText = "";
        let interim = "";
        for (let i = event.resultIndex; i < event.results.length; i += 1) {
          const transcript = event.results[i][0].transcript;
          if (event.results[i].isFinal) finalText += transcript;
          else interim += transcript;
        }
        if (interim) setPetStatusV2(`待命中：${interim}`);
        if (interim) {
          setStateV2("listening");
          updateVoicePresenceV2("direct", "listening", interim);
        }
        if (finalText.trim()) processDirectSpeechV2(finalText.trim());
      };
      stateV2.directRecognition.onerror = (event) => {
        setPetStatusV2("直达语音已中断，可重新点击按钮恢复待命");
        elsV2.directVoiceTrigger.classList.remove("listening");
        stateV2.directListening = false;
        if (event.error === "not-allowed" || event.error === "service-not-allowed") stopDirectVoiceV2(false);
      };
      stateV2.directRecognition.onend = () => {
        stateV2.directListening = false;
        elsV2.directVoiceTrigger.classList.remove("listening");
        if (stateV2.standbyEnabled) window.setTimeout(beginDirectVoiceV2, 380);
      };
      stateV2.standbyEnabled = true;
      beginDirectVoiceV2();
      toastV2("直达语音待命已开启。", "success", "海小南待命");
      showBubbleV2({
        title: "直达语音已开启",
        copy: "现在先说“小南小南”，再直接说“打开合同交底表”或“帮我订明天下午3点会议室”等命令。",
        quickItems: DEMO_COMMANDS_V2,
        sticky: true
      });
      scheduleAmbientV2();
    }

    function bindHistoryV2() {
      const update = () => {
        const keyword = elsV2.historySearch.value.trim().toLowerCase();
        elsV2.clearSearch.style.display = keyword ? "block" : "none";
        let visibleCount = 0;
        elsV2.historyItems.forEach((item) => {
          const title = item.dataset.title.toLowerCase();
          const matched = !keyword || title.includes(keyword);
          item.classList.toggle("hidden", !matched);
          if (matched) visibleCount += 1;
        });
        elsV2.searchEmpty.style.display = visibleCount === 0 ? "block" : "none";
      };
      elsV2.historySearch.addEventListener("input", update);
      elsV2.clearSearch.addEventListener("click", () => {
        elsV2.historySearch.value = "";
        update();
      });
    }

    function bindModalShellV2() {
      elsV2.modalClose.addEventListener("click", closeModalV2);
      elsV2.modalLayer.addEventListener("click", (event) => {
        if (event.target === elsV2.modalLayer) closeModalV2();
      });
    }

    function bindTopV2() {
      elsV2.micTrigger.addEventListener("click", startTextVoiceV2);
      elsV2.directVoiceTrigger.addEventListener("click", toggleDirectVoiceV2);
      elsV2.listenCancel.addEventListener("click", () => stopTextVoiceV2(true));
      elsV2.sendTrigger.addEventListener("click", () => {
        const value = elsV2.mainInput.value.trim();
        if (!value) {
          toastV2("请输入内容，或直接点击麦克风说一句话。", "info", "海小南提示");
          return;
        }
        processCommandV2(value, "manual");
      });
      elsV2.mainInput.addEventListener("keydown", (event) => {
        if (event.key === "Enter" && !event.shiftKey) {
          event.preventDefault();
          elsV2.sendTrigger.click();
        }
      });
    }

    function bindDigitalHumanV2() {
      const pet = elsV2.digitalHuman;
      let dragging = false;
      let dragStartX = 0;
      let dragStartY = 0;
      let offsetX = 0;
      let offsetY = 0;
      let lastMoveX = 0;
      let lastMoveY = 0;
      let lastMoveAt = 0;

      const snapToEdge = () => {
        const rect = pet.getBoundingClientRect();
        const snapX = rect.left < window.innerWidth / 2 ? 14 : window.innerWidth - pet.offsetWidth - 14;
        pet.style.left = `${snapX}px`;
        pet.style.right = "auto";
        pet.style.bottom = "auto";
        positionBubbleV2();
      };

      pet.addEventListener("mouseenter", (event) => {
        if (!dragging) setStateV2("hover");
        dispatchAvatarEventV2("pointermove", { clientX: event.clientX, clientY: event.clientY });
        if (!pet.classList.contains("show-bubble")) {
          showBubbleV2({
            title: "点我、双击我，或者直接说“小南小南”",
            copy: stateV2.standbyEnabled
              ? "我现在已经在待命，你也可以直接点下面的预设命令看重点演示。"
              : "双击数字人可直接开启待命，单击会展开预设命令和快捷入口。",
            quickItems: DEMO_COMMANDS_V2,
            sticky: false
          });
        }
      });

      pet.addEventListener("mouseleave", () => {
        if (!dragging) setStateV2(restingStateV2());
        dispatchAvatarEventV2("pointerleave");
      });

      pet.addEventListener("mousemove", (event) => {
        if (!dragging) dispatchAvatarEventV2("pointermove", { clientX: event.clientX, clientY: event.clientY });
      });

      pet.addEventListener("click", (event) => {
        const dx = Math.abs(event.clientX - dragStartX);
        const dy = Math.abs(event.clientY - dragStartY);
        if (stateV2.dragMoved || dx > 5 || dy > 5) {
          stateV2.dragMoved = false;
          return;
        }
        setStateV2("awake", 1100);
        if (pet.classList.contains("show-bubble")) hideBubbleV2();
        else {
          showBubbleV2({
            title: "海小南快捷演示",
            copy: stateV2.standbyEnabled
              ? "我已经在待命，你也可以直接点下面的命令快速走一遍演示链路。"
              : "如果现场语音受环境影响，直接点下面的命令，也会走与真实语音相同的调度链路。",
            quickItems: DEMO_COMMANDS_V2,
            sticky: true
          });
        }
      });

      pet.addEventListener("dblclick", () => {
        toggleDirectVoiceV2();
        setStateV2("awake", 1400);
      });

      const startDrag = (clientX, clientY) => {
        const rect = pet.getBoundingClientRect();
        dragging = true;
        stateV2.dragMoved = false;
        dragStartX = clientX;
        dragStartY = clientY;
        offsetX = clientX - rect.left;
        offsetY = clientY - rect.top;
        lastMoveX = clientX;
        lastMoveY = clientY;
        lastMoveAt = performance.now();
        setStateV2("dragging");
        dispatchAvatarEventV2("dragstart", { clientX, clientY });
      };

      const moveDrag = (clientX, clientY) => {
        if (!dragging) return;
        stateV2.dragMoved = true;
        const maxX = window.innerWidth - pet.offsetWidth - 8;
        const maxY = window.innerHeight - pet.offsetHeight - 8;
        const nextX = Math.min(Math.max(clientX - offsetX, 8), maxX);
        const nextY = Math.min(Math.max(clientY - offsetY, 72), maxY);
        const centerX = nextX + pet.offsetWidth / 2;
        const tilt = ((clientX - centerX) / 13).toFixed(2);
        const deltaX = clientX - dragStartX;
        const deltaY = clientY - dragStartY;
        const travel = Math.min(1.4, Math.hypot(deltaX, deltaY) / 120);
        const pull = Math.min(1.35, Math.abs(deltaX) / 110);
        const lift = Math.min(1.1, Math.max(0, dragStartY - clientY) / 90);
        const now = performance.now();
        const dt = Math.max(16, now - lastMoveAt);
        const velocityX = Math.max(-1.2, Math.min(1.2, (clientX - lastMoveX) / dt * 10));
        const velocityY = Math.max(-1.2, Math.min(1.2, (clientY - lastMoveY) / dt * 10));
        pet.style.left = `${nextX}px`;
        pet.style.top = `${nextY}px`;
        pet.style.right = "auto";
        pet.style.bottom = "auto";
        pet.style.setProperty("--drag-tilt", `${tilt}deg`);
        dispatchAvatarEventV2("dragmove", { clientX, clientY, tilt: Number(tilt), pull, lift, travel, velocityX, velocityY });
        lastMoveX = clientX;
        lastMoveY = clientY;
        lastMoveAt = now;
        positionBubbleV2();
      };

      const endDrag = () => {
        if (!dragging) return;
        dragging = false;
        pet.style.removeProperty("--drag-tilt");
        dispatchAvatarEventV2("dragend");
